import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../auth';

export default function SignupPage() {
  const { signup, loginWithGoogle } = useAuth();
  const navigate = useNavigate();
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirm, setConfirm] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [headerSearch, setHeaderSearch] = useState('');

  const onSubmit = async (e) => {
    e.preventDefault();
    setError('');
    if (password !== confirm) {
      setError('Passwords do not match');
      return;
    }
    setLoading(true);
    try {
      await signup({ fullName, email, password });
      navigate('/', { replace: true });
    } catch (e) {
      setError('Failed to sign up.');
    } finally {
      setLoading(false);
    }
  };

  const onGoogle = async () => {
    setLoading(true);
    try {
      await loginWithGoogle();
      navigate('/', { replace: true });
    } finally {
      setLoading(false);
    }
  };

  function submitHeaderSearch() {
    const q = (headerSearch || '').trim();
    if (q) navigate(`/browse?q=${encodeURIComponent(q)}`);
    else navigate('/browse');
  }

  function onHeaderSearchKeyDown(e) {
    if (e.key === 'Enter') submitHeaderSearch();
  }

  return (
    <div className="authLayout" style={{ background: '#F6F7FB', minHeight: '100vh' }}>
      {/* Top header matching design */}
      <header className="dash__topbar" style={{ background: 'white', boxShadow: '0 1px 0 rgba(0,0,0,0.05)' }}>
        <div className="dash__brand" onClick={() => navigate('/')} style={{ cursor: 'pointer' }}>
          <span className="dash__logo" style={{ color: '#4F46E5', fontWeight: 800 }}>TradeUrTalk</span>
        </div>
        <div className="dash__right" style={{ display: 'flex', alignItems: 'center', gap: 16 }}>
          <button onClick={() => navigate('/teach')} className="link" style={{ background: 'transparent', border: 'none', color: '#111827', cursor: 'pointer' }}>Teach</button>
          <button onClick={() => navigate('/browse')} className="link" style={{ background: 'transparent', border: 'none', color: '#111827', cursor: 'pointer' }}>Browse Courses</button>
          <div style={{ position: 'relative' }}>
            <span aria-hidden style={{ position: 'absolute', left: 10, top: '50%', transform: 'translateY(-50%)', color: '#9CA3AF' }}>🔎</span>
            <input
              type="text"
              placeholder="Search..."
              value={headerSearch}
              onChange={(e) => setHeaderSearch(e.target.value)}
              onKeyDown={onHeaderSearchKeyDown}
              className="input"
              style={{ paddingLeft: 32, minWidth: 180, height: 34 }}
            />
          </div>
        </div>
      </header>

      {/* Illustration + panel layout preserved */}
      <div className="authIllustration" aria-hidden style={{ background: '#EEF2FF' }}>
        <div className="authCircle" style={{ background: 'transparent', boxShadow: 'none' }}>
          <span className="authEmoji" role="img" aria-label="learning" style={{ color: '#4F46E5', fontSize: 64 }}>📖</span>
          <div style={{ color: '#818CF8', marginTop: 12 }}>…</div>
        </div>
      </div>

      <div className="authPanel">
        <div className="authCard" style={{ borderRadius: 12, boxShadow: '0 10px 30px rgba(0,0,0,0.08)' }}>
          <h1 className="authTitle" style={{ marginBottom: 16 }}>Create your account</h1>
          {error && <div className="errorBox" style={{ marginTop: 12 }}>{error}</div>}
          <form onSubmit={onSubmit} className="authForm">
            <label className="label">Full name</label>
            <input
              className="input"
              type="text"
              placeholder="Enter your full name"
              value={fullName}
              onChange={(e) => setFullName(e.target.value)}
              required
            />
            <label className="label">Email</label>
            <input
              className="input"
              type="email"
              placeholder="Enter your email"
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              required
            />
            <label className="label">Password</label>
            <input
              className="input"
              type="password"
              placeholder="Enter your password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
            <label className="label">Confirm password</label>
            <input
              className="input"
              type="password"
              placeholder="Confirm your password"
              value={confirm}
              onChange={(e) => setConfirm(e.target.value)}
              required
            />
            <button className="btnPrimary" type="submit" disabled={loading} style={{ width: '100%', marginTop: 12, background: '#4F46E5' }}>
              {loading ? 'Creating account…' : 'Continue'}
            </button>
          </form>

          {/* Divider */}
          <div style={{ display: 'flex', alignItems: 'center', gap: 12, margin: '16px 0' }}>
            <div style={{ height: 1, background: '#E5E7EB', flex: 1 }} />
            <span style={{ color: '#9CA3AF' }}>or</span>
            <div style={{ height: 1, background: '#E5E7EB', flex: 1 }} />
          </div>

          <button className="btnGoogle" onClick={onGoogle} disabled={loading} style={{ width: '100%', background: 'white', color: '#111827', border: '1px solid #E5E7EB' }}>
            <svg width="18" height="18" viewBox="0 0 48 48" aria-hidden focusable="false"><path fill="#FFC107" d="M43.6 20.5H42V20H24v8h11.3C33.8 32.7 29.3 36 24 36c-6.6 0-12-5.4-12-12s5.4-12 12-12c3 0 5.7 1.1 7.7 3l5.7-5.7C33.8 6.3 29.2 4 24 4 12.9 4 4 12.9 4 24s8.9 20 20 20 20-8.9 20-20c0-1.2-.1-2.3-.3-3.5z"/><path fill="#FF3D00" d="M6.3 14.7l6.6 4.8C14.9 16.3 19.1 14 24 14c3 0 5.7 1.1 7.7 3l5.7-5.7C33.8 6.3 29.2 4 24 4 16.4 4 9.8 8.3 6.3 14.7z"/><path fill="#4CAF50" d="M24 44c5.2 0 9.9-2 13.4-5.3l-6.2-5.2C29.1 34.8 26.7 36 24 36c-5.2 0-9.6-3.3-11.3-8l-6.5 5C9.7 39.6 16.3 44 24 44z"/><path fill="#1976D2" d="M43.6 20.5H42V20H24v8h11.3c-1 2.4-2.8 4.4-5.1 5.7l.1.1 6.2 5.2c-.4.3 7.4-4.7 7.4-14 0-1.2-.1-2.3-.3-3.5z"/></svg>
            <span style={{ marginLeft: 8 }}>Continue with Google</span>
          </button>

          <div className="authAlt" style={{ marginTop: 16 }}>
            Already have an account? <Link to="/login" className="link" style={{ color: '#4F46E5' }}>Log in</Link>
          </div>
        </div>
      </div>
    </div>
  );
}
